sys_script_include.script:
var CycloidIntegration = Class.create();
CycloidIntegration.prototype = {
  initialize: function() {},

  // Constant for your app scope
  SCOPE: 'x_1829062_cycloi_1',

  // Fetch stacks from Cycloid API
  getStacks: function() {
    var apiBase = gs.getProperty(this.SCOPE + '.cy_api_url', '').replace(/\/+$/, '');
    var org = gs.getProperty(this.SCOPE + '.cy_organization_canonical', '');
    var apiKey = gs.getProperty(this.SCOPE + '.cy_api_key', '');

    if (!apiBase || !org || !apiKey) {
      gs.error("Cycloid configuration incomplete (missing properties)");
      return [];
    }

    var endpoint = apiBase + '/organizations/' + encodeURIComponent(org) +
                   '/service_catalogs?infra_import_stack[eq]=false&page_index=1&page_size=10000';

    var rm = new sn_ws.RESTMessageV2();
    rm.setHttpMethod('get');
    rm.setEndpoint(endpoint);
    rm.setRequestHeader('Accept', 'application/json');
    rm.setRequestHeader('Authorization', 'Bearer ' + apiKey);

    var response = rm.execute();
    var status = response.getStatusCode();
    var body = response.getBody();

    if (status < 200 || status >= 300) {
      gs.error('Cycloid API error (' + status + '): ' + body);
      return [];
    }

    var json = JSON.parse(body);
    return json.items || json.stacks || json || [];
  },

  // Sync stacks to extended Service Catalog table
  syncStacks: function() {
    var catSysId = gs.getProperty(this.SCOPE + '.cy_catalog_category', '');
    if (!catSysId) {
      gs.error("Property cy_catalog_category not defined (put the sys_id of a catalog category)");
      return;
    }

    var stacks = this.getStacks();

    stacks.forEach(function(stack) {
      var stackRef = stack.ref;
      var name = stack.name || stackRef;
      var desc = stack.description || '';
      var icon = (stack.icon && stack.icon.url) || stack.icon || '';

      // Use extended table for Cycloid stacks
      var gr = new GlideRecord(this.SCOPE + '_cycloid_stack_item');
      gr.addQuery('cycloid_stack_ref', stackRef);
      gr.query();

      if (gr.next()) {
        // Update existing item
        gr.short_description = name;
        gr.description = desc;
        if (icon) gr.picture = icon;
        gr.category = catSysId;
        gr.update();
      } else {
        // Create new item
        gr.initialize();
        gr.name = name;
        gr.short_description = name;
        gr.description = desc;
        if (icon) gr.picture = icon;
        gr.category = catSysId;
        gr.cycloid_stack_ref = stackRef;
        gr.insert();
      }
    });

    gs.info("[CycloidIntegration] Synced " + stacks.length + " Cycloid stacks to Service Catalog");
  },

  type: 'CycloidIntegration'
};
